        err,
        originId,
        organizationId: params.organizationId,
        relationshipId: params.relationshipId,
        op: params.op,
        changes: params.changes,
      },
      '[insert-event] edge change audit event DROPPED after retry — edge history is missing this row'
    );
  });
}

