450	        // inside a single transaction. `SET LOCAL` is scoped to the
451	        // transaction and reverts on COMMIT, and the whole `db.begin` callback
452	        // runs on ONE reserved connection — so the `replica` role can never
453	        // leak back onto a pooled connection (the bug fixed in #1607).
454	        //
455	        // `session_replication_role` is superuser-only; on a non-superuser test
456	        // role (the PG15+ fresh-`createdb` shape from #950) we skip the disable
457	        // entirely. `TRUNCATE … CASCADE` respects FK ordering on its own, so
458	        // this only forgoes the speedup, never correctness.
459	        await db.begin(async (tx) => {
460	          await tx.unsafe(`SET LOCAL session_replication_role = 'replica'`);
461	          await tx.unsafe(`TRUNCATE ${quotedTables} CASCADE`);
462	        });
463	      } else {
464	        await db.unsafe(`TRUNCATE ${quotedTables} CASCADE`);
465	      }
466	      return;
467	    } catch (err) {
468	      const code = (err as { code?: string } | null)?.code;
469	      // 42P01 (undefined_table): a listed table disappeared mid-truncate.
470	      // Tolerated — the next test re-runs migrations/cleanup anyway.
471	      if (code === '42P01') return;
472	      // 40P01 (deadlock_detected): a leaked background poller's DML held FK
473	      // row-share locks in the opposite order. Retry after a short backoff.
474	      if (code === '40P01' && attempt < TRUNCATE_DEADLOCK_RETRIES) {
475	        await new Promise((resolve) => setTimeout(resolve, 25 * (attempt + 1)));
