477	      }
478	      // Anything else — a permission error, a failed `SET LOCAL`, a transaction
479	      // abort, a lock timeout — or a deadlock that survived every retry is a
480	      // real cleanup failure that would leave the DB dirty for the next test,
481	      // so re-throw rather than silently swallow.
482	      throw err;
483	    }
484	  }
