29	import { describe, expect, test } from 'bun:test';
30	import { truncateAllTables } from '../../__tests__/setup/test-db';
31	
32	type Outcome = '40P01' | '42P01' | '42501' | 'ok';
33	
34	function pgError(code: string): Error {
35	  return Object.assign(new Error(`pg error ${code}`), { code });
36	}
37	
38	/**
39	 * Fake `postgres.Sql` whose every TRUNCATE attempt (one `begin` call or one
40	 * `unsafe` call) consumes the next scripted outcome; the last entry repeats.
41	 */
42	function fakeDb(script: Outcome[]) {
43	  let i = 0;
44	  const consume = () => {
45	    const outcome = script[Math.min(i, script.length - 1)];
46	    i++;
47	    if (outcome !== 'ok') throw pgError(outcome);
48	  };
49	  const db = {
50	    attempts: 0,
51	    async unsafe(_sql: string) {
