/**
 * Regression for #2818: `cleanupTestDatabase()`'s `TRUNCATE … CASCADE` must
 * FAIL FAST when another session holds a conflicting lock, instead of blocking
 * until the test timeout.
 *
 * `truncateAllTables` already retries `40P01` (deadlock), which covers a leaked
 * background poller whose INSERT grabs FK locks in the opposite order — Postgres
 * detects that cycle and aborts a victim in milliseconds.
 *
 * It did NOT cover the other shape: a poller (or any session) that holds a lock
 * WITHOUT forming a cycle. There is no deadlock to detect, so `TRUNCATE` waits
 * for `AccessExclusiveLock` forever. In CI that surfaced as every subsequent
 * `beforeEach` dying at the 30s per-test cap until the job hit GitHub's
 * 15-minute ceiling, taking the required `integration` fan-in red on unrelated
 * PRs — with the Postgres log showing a blocked `TRUNCATE` and a stream of
 * `skipping analyze … lock not available`.
 *
 * A real database is load-bearing here: the failure is Postgres lock-wait
 * behaviour, which a scripted fake cannot reproduce. The scripted-fake tests for
 * the retry/exhaustion branches live in `cleanup-truncate-deadlock-retry.test.ts`.
 *
 * The probe uses its own scratch table, so it never truncates anything another
 * co-running suite depends on.
 */

import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import postgres from 'postgres';
import { truncateAllTables } from '../../__tests__/setup/test-db';
import { ensureDbForGatewayTests } from '../../gateway/__tests__/helpers/db-setup';

const PROBE_TABLE = 'truncate_lock_probe_2818';

let owner: postgres.Sql;
let blocker: postgres.Sql;

beforeAll(async () => {
  await ensureDbForGatewayTests();
  const url = process.env.DATABASE_URL as string;
  owner = postgres(url, { max: 2, onnotice: () => {} });
  blocker = postgres(url, { max: 1, onnotice: () => {} });
  await owner.unsafe(`CREATE TABLE IF NOT EXISTS ${PROBE_TABLE} (id int)`);
});

afterAll(async () => {
  await owner?.unsafe(`DROP TABLE IF EXISTS ${PROBE_TABLE}`).catch(() => {});
  await owner?.end({ timeout: 5 });
  await blocker?.end({ timeout: 5 });
});

/**
 * Hold `ACCESS EXCLUSIVE` on the probe table from a second session and keep the
 * transaction open until `release()` is called. This is the non-cyclic shape:
 * TRUNCATE simply queues behind it, so Postgres never raises a deadlock.
 */
async function holdConflictingLock(): Promise<{ release: () => void }> {
  let release!: () => void;
  const held = new Promise<void>((resolve) => {
    release = resolve;
  });
  const locked = new Promise<void>((resolve, reject) => {
    blocker
      .begin(async (tx) => {
        await tx.unsafe(`LOCK TABLE ${PROBE_TABLE} IN ACCESS EXCLUSIVE MODE`);
        resolve();
        await held;
      })
      .catch(reject);
  });
  await locked;
  return { release };
}

describe('truncateAllTables — blocked-lock timeout (#2818)', () => {
  for (const canDisableTriggers of [true, false]) {
    test(
      `fails fast instead of blocking forever (canDisableTriggers=${canDisableTriggers})`,
      async () => {
        const { release } = await holdConflictingLock();
        const startedAt = performance.now();
        try {
          await expect(
            truncateAllTables(owner, `"${PROBE_TABLE}"`, canDisableTriggers)
          ).rejects.toThrow();
        } finally {
          release();
        }
        const elapsed = performance.now() - startedAt;

        // The point of the fix: bounded, and well inside the 30s per-test cap
        // that CI was dying on. Before the fix this never rejects at all — the
        // TRUNCATE waits on the lock and the test dies by timeout, which is
        // exactly the CI symptom.
        expect(elapsed).toBeLessThan(20_000);
      },
      25_000
    );
  }

  test('still succeeds when nothing holds a conflicting lock', async () => {
    await owner.unsafe(`INSERT INTO ${PROBE_TABLE} (id) VALUES (1)`);
    await truncateAllTables(owner, `"${PROBE_TABLE}"`, true);
    const rows = await owner.unsafe(`SELECT count(*)::int AS n FROM ${PROBE_TABLE}`);
    expect(rows[0]?.n).toBe(0);
  });
});

