const TRUNCATE_DEADLOCK_RETRIES = 8;

/**
 * Ceiling on how long the cleanup TRUNCATE waits for any single lock (#2818).
 *
 * The deadlock retry below only helps when the conflicting session forms a
 * CYCLE — Postgres detects that and aborts a victim in milliseconds. A session
 * that merely holds a lock without a cycle produces no deadlock, so `TRUNCATE`
 * queues behind it indefinitely. In CI that meant every following `beforeEach`
 * died at the 30s per-test cap until the job hit GitHub's 15-minute ceiling,
 * failing the required `integration` fan-in on unrelated PRs.
 *
 * 2s is ~13x the measured whole-database truncate cost (~150ms for 76 tables,
 * profiled in `run-gateway-test-lanes.mjs`) and the retry budget keeps the worst
 * case near 8s — an order of magnitude inside the 30s per-test timeout, so a
 * genuinely stuck cleanup reports WHO is blocking instead of dying anonymously.
 */
const TRUNCATE_LOCK_TIMEOUT_MS = 2_000;
const TRUNCATE_LOCK_RETRIES = 3;

/**
 * Best-effort description of the sessions blocking us, for the error thrown
 * once the lock retries are exhausted. Diagnostics must never mask the real
 * failure, so every error here is swallowed.
 */
async function describeLockBlockers(db: postgres.Sql): Promise<string> {
  try {
    const rows = await db.unsafe(`
      SELECT pid, state, wait_event_type, wait_event,
             left(regexp_replace(query, '\\s+', ' ', 'g'), 200) AS query
      FROM pg_stat_activity
      WHERE datname = current_database()
        AND pid <> pg_backend_pid()
        AND state IS DISTINCT FROM 'idle'
      ORDER BY xact_start NULLS LAST
      LIMIT 10
    `);
    if (rows.length === 0) return 'no non-idle sessions visible in pg_stat_activity';
    return rows
      .map(
        (r) =>
          `pid=${r.pid} state=${r.state} wait=${r.wait_event_type ?? '-'}/${r.wait_event ?? '-'} query=${r.query}`
      )
      .join('\n  ');
  } catch (err) {
    return `could not read pg_stat_activity: ${(err as Error)?.message ?? err}`;
  }
}

