/**
 * Batch edge writes for first-party materializers.
 *
 * The ACL graph, the GitHub team graph, channel `about` edges and the
 * auto-linker each hand-rolled the same `INSERT INTO entity_relationships …
 * ON CONFLICT … ` statement, one round trip per edge. Three copies agreed; the
 * fourth (auto-linker) dropped the conflict clause for a preceding `SELECT`,
 * which is a check-then-write race rather than an idempotent write. This module
 * is the single statement they now share.
 *
 * Deliberately NOT the same thing as `relationship-validation.ts`. That module
 * guards the caller-facing `manage_entity` link surface: its `validateSource`
 * accepts only `ui|llm|feed|api` (so it would reject the `config`/`manual`
 * sources reconcilers own), and its `checkDuplicateEdge` raises a 409 where a
 * materializer wants an idempotent no-op. The two pure predicates that DO apply
 * to both surfaces are reused from there.
 *
 * Also not a general edge kernel: `entity-merge`'s repoint/tombstone and
 * `force_delete_tree`'s hard delete stay where they are. Their SQL is
 * ordering-dependent and set-based, and routing it through a row-shaped writer
 * would need enough escape hatches to make the writer meaningless.
 */

import { type DbClient, getDb, pgBigintArray } from '../db/client';
import { validateConfidence } from './relationship-validation';

/** One directed edge to write. Everything else is constant across the batch. */
export interface EdgePair {
  fromEntityId: number;
  toEntityId: number;
}

export interface UpsertEdgesParams {
  /** Pool or transaction. This function never opens a transaction of its own. */
  db: DbClient;
  organizationId: string;
  relationshipTypeId: number;
  pairs: EdgePair[];
  /** Row `source`. Reconcilers pass their own (`config`, `manual`); syncs pass `feed`. */
  source: string;
  confidence?: number | null;
  createdBy?: string | null;
  /** Constant for the whole batch — group calls by metadata rather than mixing. */
  metadata?: Record<string, unknown> | null;
  /**
   * `ignore` leaves an existing live edge exactly as it is.
   * `update` refreshes metadata, source and `updated_by` on it.
   */
  onConflict: 'ignore' | 'update';
}

export interface UpsertEdgesResult {
  /** Edges that did not exist live before this call. */
  created: number[];
  /** Edges that already existed live. Empty ids are impossible — these are real rows. */
  existing: number[];
  /** Pairs dropped because both ends were the same entity. */
  skippedSelf: number;
}

/**
 * Find-or-create an org-scoped relationship type.
 *
 * `description` only lands on first create; a type that already exists keeps
 * whatever description it was created with. That is why this is shared rather
 * than copied — two copies with different descriptions silently resolved to
 * whichever ran first.
 */
export async function ensureRelationshipType(params: {
  organizationId: string;
  slug: string;
  name: string;
  description: string;
  isSymmetric?: boolean;
  db?: DbClient;
}): Promise<number> {
  const sql = params.db ?? getDb();
  const rows = await sql<{ id: number }>`
    INSERT INTO entity_relationship_types
      (slug, name, description, organization_id, is_symmetric, created_by, created_at, updated_at)
    VALUES
      (${params.slug}, ${params.name}, ${params.description}, ${params.organizationId},
       ${params.isSymmetric ?? false}, NULL, current_timestamp, current_timestamp)
    ON CONFLICT (organization_id, slug) WHERE status = 'active'
    DO UPDATE SET updated_at = EXCLUDED.updated_at
    RETURNING id
  `;
  return Number(rows[0].id);
}

/**
 * Write a batch of directed edges of one type in a single statement.
 *
 * The live-triple unique index (`from, to, type` where `deleted_at IS NULL`) is
 * what makes this idempotent, so a concurrent writer racing the same pair loses
 * harmlessly instead of raising. The pre-read below only CLASSIFIES the result
 * into created vs already-existing; correctness never depends on it.
 *
 * A tombstoned row for the same triple is not a conflict — the index is partial
 * — so this inserts a fresh live row beside it, which is the existing behaviour
 * of every call site this replaces.
 */
export async function upsertEdges(params: UpsertEdgesParams): Promise<UpsertEdgesResult> {
  const { db, organizationId, relationshipTypeId, source, onConflict } = params;
  validateConfidence(params.confidence);

  // Dedupe within the batch. Required, not tidiness: `ON CONFLICT DO UPDATE`
  // refuses to touch the same row twice in one statement.
  const seen = new Set<string>();
  const pairs: EdgePair[] = [];
  let skippedSelf = 0;
  for (const pair of params.pairs) {
    const from = Number(pair.fromEntityId);
    const to = Number(pair.toEntityId);
    if (from === to) {
      skippedSelf++;
      continue;
    }
    const key = `${from}:${to}`;
    if (seen.has(key)) continue;
    seen.add(key);
    pairs.push({ fromEntityId: from, toEntityId: to });
  }
  if (pairs.length === 0) return { created: [], existing: [], skippedSelf };

  const froms = pairs.map((p) => p.fromEntityId);
  const tos = pairs.map((p) => p.toEntityId);

  // One read for the whole batch, replacing the per-edge existence check the
  // auto-linker used to run. Keyed on the same triple the unique index uses.
  const before = await db<{ id: number; from_entity_id: number; to_entity_id: number }>`
    SELECT id, from_entity_id, to_entity_id
    FROM entity_relationships
    WHERE organization_id = ${organizationId}
      AND relationship_type_id = ${relationshipTypeId}
      AND deleted_at IS NULL
      AND (from_entity_id, to_entity_id) IN (
        SELECT f, t
        FROM unnest(${pgBigintArray(froms)}::bigint[], ${pgBigintArray(tos)}::bigint[]) AS v(f, t)
      )
  `;
  const existing = before.map((row) => Number(row.id));

  const conflictAction =
    onConflict === 'update'
      ? db`DO UPDATE SET
            metadata = EXCLUDED.metadata,
            source = EXCLUDED.source,
            updated_by = EXCLUDED.updated_by,
            updated_at = current_timestamp`
      : db`DO NOTHING`;

  const written = await db<{ id: number }>`
    INSERT INTO entity_relationships (
      organization_id, from_entity_id, to_entity_id, relationship_type_id,
      metadata, confidence, source, created_by, updated_by, created_at, updated_at
    )
    SELECT
      ${organizationId}, v.f, v.t, ${relationshipTypeId},
      ${params.metadata ? db.json(params.metadata) : null},
      ${params.confidence ?? null}, ${source},
      ${params.createdBy ?? null}, ${params.createdBy ?? null},
      current_timestamp, current_timestamp
    FROM unnest(${pgBigintArray(froms)}::bigint[], ${pgBigintArray(tos)}::bigint[]) AS v(f, t)
    ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
      WHERE deleted_at IS NULL
    ${conflictAction}
    RETURNING id
  `;

  // `DO NOTHING` returns only the rows it actually inserted. `DO UPDATE` also
  // returns the rows it refreshed, so subtract the ones the pre-read saw.
  const existingSet = new Set(existing);
  const created = written.map((row) => Number(row.id)).filter((id) => !existingSet.has(id));

  return { created, existing, skippedSelf };
}

