/**
 * Entity-write transactions must never ask the POOL for a second connection.
 *
 * `withEntityWriteTransaction` holds one pooled connection for the whole write.
 * A helper inside that transaction that reaches for `getDb()` instead of the
 * caller's handle needs a SECOND connection while still holding the first, so
 * `DB_POOL_MAX` concurrent writers each hold one slot and each wait for a slot
 * that only another writer can release. Nothing times out — session waits are
 * unbounded — so the pool is dead for the life of the process.
 *
 * This is the same one-directional-dependency rule `getLockDb()` already
 * documents for session advisory locks, applied to the entity write path. It
 * surfaced as #2818: `server-integration-bun` wedging on the 15-minute cap with
 * every pooled connection sitting `idle in transaction` at the identity lookup,
 * which is the statement immediately before the offending call.
 */

import { afterAll, beforeEach, describe, expect, it } from "vitest";
import { closeDbSingleton, getDb } from "../../../db/client";
import {
  clearEntityLinkRulesCache,
  resolveSenderIdentity,
} from "../../../utils/entity-link-upsert";
import { ensureMemberEntityType } from "../../../utils/member-entity-type";
import { cleanupTestDatabase } from "../../setup/test-db";
import {
  addUserToOrganization,
  createTestOrganization,
  createTestUser,
} from "../../setup/test-fixtures";

/**
 * Small enough that the starvation is deterministic rather than load-dependent:
 * with N concurrent writers and a pool of N, one extra connection request can
 * never be served.
 */
const POOL_MAX = 2;

/** Well under the 15-minute CI cap, well over a healthy run (milliseconds). */
const DEADLOCK_TIMEOUT_MS = 15_000;

async function withPoolMax<T>(max: number, run: () => Promise<T>): Promise<T> {
  const previous = process.env.DB_POOL_MAX;
  // The pool size is read when the singleton is constructed, so the existing
  // one has to go before the new bound takes effect.
  await closeDbSingleton();
  process.env.DB_POOL_MAX = String(max);
  try {
    return await run();
  } finally {
    await closeDbSingleton();
    if (previous === undefined) delete process.env.DB_POOL_MAX;
    else process.env.DB_POOL_MAX = previous;
  }
}

describe("entity write transactions do not starve the connection pool", () => {
  let orgId: string;

  beforeEach(async () => {
    await cleanupTestDatabase();
    // The creator lookup is memoized per org, and a cache HIT never touches the
    // pool — so a stale entry would hide the very starvation under test.
    clearEntityLinkRulesCache();
    const org = await createTestOrganization({ name: "Pool Starvation Org" });
    orgId = org.id;
    const user = await createTestUser();
    await addUserToOrganization(user.id, orgId, "owner");
    await ensureMemberEntityType(orgId);
  });

  afterAll(async () => {
    // Leave the shared singleton in the shape the rest of the suite expects.
    await closeDbSingleton();
  });

  it("resolves concurrent unknown senders with DB_POOL_MAX writers in flight", async () => {
    const resolved = await withPoolMax(POOL_MAX, async () => {
      const sql = getDb();
      // Distinct identifiers so every call MISSES and takes the mint path —
      // the branch that opens a transaction. A hit answers from the pooled
      // read and never holds a connection across a second query.
      const senders = Array.from({ length: POOL_MAX }, (_, index) =>
        resolveSenderIdentity(sql, {
          orgId,
          connectorKey: "pool-starvation",
          mintEntityType: "person",
          title: `Sender ${index}`,
          identities: [
            {
              namespace: "pool_starvation_user_id",
              identifier: `U_STARVE_${index}`,
              matchOnly: false,
              primary: true,
            },
          ],
        }),
      );

      // Racing a timer rather than leaning on the suite timeout: a starved pool
      // reports as this assertion, not as an unattributed 15-minute hang.
      let timer: ReturnType<typeof setTimeout> | undefined;
      const deadline = new Promise<"timeout">((resolve) => {
        timer = setTimeout(() => resolve("timeout"), DEADLOCK_TIMEOUT_MS);
      });
      try {
        return await Promise.race([Promise.all(senders), deadline]);
      } finally {
        if (timer) clearTimeout(timer);
      }
    });

    expect(resolved).not.toBe("timeout");
    const ids = resolved as Array<number | null>;
    expect(ids).toHaveLength(POOL_MAX);
    // Every sender minted a distinct entity — proving the calls did real work
    // rather than short-circuiting before they could contend for a connection.
    expect(ids.every((id) => typeof id === "number")).toBe(true);
    expect(new Set(ids).size).toBe(POOL_MAX);
  });
});

