/**
 * Close and reset the singleton PostgreSQL client.
 * Primarily used by tests that need strict connection handoff between setup and workers.
 *
 * `timeoutSeconds` caps how long the close waits for in-flight work before
 * destroying the sockets. The default (omitted) waits indefinitely, which is
 * what a graceful shutdown wants — but a caller diagnosing a STARVED pool
 * cannot wait for queries that are, by definition, never going to finish. Pass
 * 0 there to force the close and get a usable pool back.
 */
export async function closeDbSingleton(options?: { timeoutSeconds?: number }): Promise<void> {
  const end = options?.timeoutSeconds === undefined ? undefined : { timeout: options.timeoutSeconds };
  if (rawDbSingleton?.end) {
    await rawDbSingleton.end(end);
  } else if (dbSingleton?.end) {
    await dbSingleton.end(end);
  }
  dbSingleton = null;
  rawDbSingleton = null;
  if (lockDbSingleton) {
    await lockDbSingleton.end(end);
    lockDbSingleton = null;
  }
}

