// Collect all rules across all relationship types. Two separate things make a
// type read-only, and both must hide the inline delete affordance and the
// create-rule shortcut while still surfacing the type so users can see it:
//
//   - public-catalog types, which this org does not own; and
//   - authorization-bearing types (`member_of`), whose edges gate access and
//     which the server refuses to modify at all — every write action 403s via
//     assertNotAuthorizationType. Owning them is exactly why they land in the
//     local bucket, so ownership alone cannot tell them apart.
const activeTypes = (relationshipTypes || []).filter((rt) => rt.status === 'active');
const ownedTypes = activeTypes.filter(
  (rt) => !rt.organization_slug || rt.organization_slug === orgContext?.slug
);
const localTypes = ownedTypes.filter((rt) => rt.purpose !== PURPOSE_AUTHORIZATION);
const accessManagedTypes = ownedTypes.filter(
  (rt) => rt.purpose === PURPOSE_AUTHORIZATION
);
const crossOrgTypes = activeTypes.filter(
  (rt) => rt.organization_slug && rt.organization_slug !== orgContext?.slug
);

