export function buildProofBody(proof: UiReviewProof): string {
  const encoded = Buffer.from(JSON.stringify(proof), "utf8").toString(
    "base64url"
  );
  const marker = `${PROOF_MARKER}${encoded} -->`;
  return `${marker}
## UI proof

