// @vitest-environment jsdom
// TEMPORARY — UI proof capture for lobu#2839 / owletto#881. Delete after use.
// Renders RelationshipTypesTab against the EXACT payload returned by a booted
// local instance (GET manage_entity_schema list, org `local-install`) and dumps
// the structural facts the review cares about: which types are offered as
// editable, which are read-only, and where the remove affordances are.
import { render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

const REL_TYPES = [
	{
		id: 3,
		slug: "member_of",
		name: "Member of",
		organization_slug: "local-install",
		status: "active",
		purpose: "authorization",
		is_symmetric: false,
	},
	{
		id: 2,
		slug: "reports_to",
		name: "Reports to",
		organization_slug: "local-install",
		status: "active",
		purpose: null,
		is_symmetric: false,
	},
	{
		id: 1,
		slug: "works_at",
		name: "Works at",
		organization_slug: "local-install",
		status: "active",
		purpose: null,
		is_symmetric: false,
	},
];

const RULES: Record<string, unknown[]> = {
	member_of: [
		{ id: 3, source_entity_type_slug: "person", target_entity_type_slug: "team" },
	],
	reports_to: [
		{ id: 2, source_entity_type_slug: "person", target_entity_type_slug: "person" },
	],
	works_at: [
		{ id: 1, source_entity_type_slug: "person", target_entity_type_slug: "company" },
	],
};

vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({
		orgContext: { organizationId: "org_z9Mi4u4aBh4", slug: "local-install" },
	}),
}));

vi.mock("@/lib/api", async (importOriginal) => {
	const actual = await importOriginal<Record<string, unknown>>();
	return {
		...actual,
		PURPOSE_AUTHORIZATION: "authorization",
		useRelationshipTypes: () => ({ data: REL_TYPES, isLoading: false }),
		useEntityTypesAdmin: () => ({
			data: [
				{ slug: "person", name: "Person", organization_slug: "local-install" },
				{ slug: "company", name: "Company", organization_slug: "local-install" },
				{ slug: "team", name: "Team", organization_slug: "local-install" },
			],
		}),
		useRelationshipTypeRules: (slug: string | null) => ({
			data: slug ? RULES[slug] || [] : [],
		}),
		useRemoveRelationshipTypeRule: () => ({ isPending: false, mutate: vi.fn() }),
		useCreateRelationshipType: () => ({ isPending: false, mutateAsync: vi.fn() }),
		useAddRelationshipTypeRule: () => ({ isPending: false, mutateAsync: vi.fn() }),
	};
});

import { RelationshipTypesTab } from "./relationship-types-tab";

describe("UI PROOF", () => {
	it("dumps the rendered structure", () => {
		const { container } = render(
			<RelationshipTypesTab
				entityType={
					{ slug: "person", name: "Person" } as unknown as Parameters<
						typeof RelationshipTypesTab
					>[0]["entityType"]
				}
			/>,
		);

